// Вход: items[0].json.body (или .data) — HTML страницы каталога
const html = (items?.[0]?.json?.body ?? items?.[0]?.json?.data ?? '').toString();

// Универсальный извлекатель JSON после window.SOMETHING = {...};
function extractJsonByPrefix(fullHtml, regexWithGroup1Json) {
  const m = fullHtml.match(regexWithGroup1Json);
  if (!m) return null;
  const raw = m[1].trim();
  try {
    return JSON.parse(raw);
  } catch (e) {
    // Попытка подчистить хвосты ; или пробелы
    const cleaned = raw.replace(/;?\s*$/, '');
    try { return JSON.parse(cleaned); } catch (e2) { return null; }
  }
}

// 1) digitalData (основной, "чистый" список)
const dd = extractJsonByPrefix(
  html,
  /window\.digitalData\s*=\s*(\{[\s\S]*?\})\s*;/
);

let catalog = [];
if (dd?.listing?.items?.length) {
  catalog = dd.listing.items.map(p => ({
    id: p.id ?? p.productId ?? null,
    mpn: p.mpnCode ?? null,
    name: p.name ?? null,
    url: p.url ?? null,
    category: p.category ?? null,
    price: p.unitPrice ?? null,
    salePrice: p.unitSalePrice ?? null,
    currency: p.currency ?? null,
    stock: p.stock ?? null,
    brand: p.brand ?? null,
  }));
}

// 2) SM_PARAMS.catalog.items (добавим картинки/альт.цены/детальную ссылку)
let smCatalog = null;

// Специально берём только вложение "catalog: {...}"
const smCatalogObj = extractJsonByPrefix(
  html,
  /window\.SM_PARAMS\s*=\s*\{\s*[^]*?catalog\s*:\s*(\{[\s\S]*?\})\s*[,}][\s\S]*?;\s*\/\/?/ // более устойчиво к разметке
);

if (smCatalogObj?.items?.length) smCatalog = smCatalogObj.items;

// Смерджим по id, если есть, иначе — по имени/URL как fallback
const byKey = new Map();
for (const x of catalog) {
  const k = String(x.id ?? x.url ?? x.name ?? Math.random());
  byKey.set(k, x);
}

if (Array.isArray(smCatalog)) {
  for (const c of smCatalog) {
    const k = String(c?.id ?? c?.detailUrl ?? c?.name ?? Math.random());
    const target = byKey.get(k) || {};
    target.id = target.id ?? c.id ?? null;
    target.name = target.name ?? c.name ?? null;
    target.detailUrl = c.detailUrl ?? target.detailUrl ?? null;
    target.images = c.images ?? target.images ?? [];
    // цены
    target.priceSpecial = (c.prices && c.prices.special != null) ? c.prices.special : (target.priceSpecial ?? null);
    target.priceRecommended = (c.prices && c.prices.recommended != null) ? c.prices.recommended : (target.priceRecommended ?? null);
    byKey.set(k, target);
  }
}

let itemsOut = Array.from(byKey.values());

// 3) Пагинация: <link rel="next" href="...">
let nextUrl = null;
const nextMatch = html.match(/<link[^>]+rel=["']next["'][^>]+href=["']([^"']+)["']/i);
if (nextMatch) nextUrl = nextMatch[1];

// 4) Метаданные листинга (если есть в digitalData)
const _meta = {
  resultCount: dd?.listing?.resultCount ?? null,
  pagesCount: dd?.listing?.pagesCount ?? null,
  currentPage: dd?.listing?.currentPage ?? null,
  nextUrl,
};

// Возвращаем: массив товаров + один служебный айтем с _meta
const out = itemsOut.map(p => ({ json: p }));
out.push({ json: { _meta } });
return out;

/**
 * INPUT:  items[0].json.body (или .data) — HTML карточки
 * OUTPUT: один айтем с базовыми полями + specs_text (чистый текст) + category
 */

const html = (items?.[0]?.json?.body ?? items?.[0]?.json?.data ?? '').toString();

// ---------- helpers ----------
function num(x){ if(x==null) return null; const v=Number(String(x).replace(/[^\d.,-]/g,'').replace(',','.')); return Number.isFinite(v)?v:null; }
function decodeHtml(s) {
  if (!s) return '';
  const map = { '&quot;':'"', '&apos;':"'", '&amp;':'&', '&lt;':'<', '&gt;':'>', '&nbsp;':' ' };
  s = s.replace(/&(?:quot|apos|amp|lt|gt|nbsp);/g, m => map[m] || m);
  s = s.replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d,10)));
  s = s.replace(/&#x([\da-fA-F]+);/g, (_, h) => String.fromCharCode(parseInt(h,16)));
  return s;
}
function extractJsonByPrefix(fullHtml, re) {
  const m = fullHtml.match(re);
  if (!m) return null;
  const raw = m[1].trim();
  try { return JSON.parse(raw); }
  catch {
    const cleaned = raw.replace(/;?\s*$/, '');
    try { return JSON.parse(cleaned); } catch { return null; }
  }
}

// ---------- базовые поля из digitalData ----------
const dd = extractJsonByPrefix(html, /window\.digitalData\s*=\s*(\{[\s\S]*?\})\s*;/);
const ddp = dd?.product || null;

const id   = ddp?.id ?? ddp?.productId ?? null;
const sku  = ddp?.id ?? null;
const mpn  = ddp?.mpnCode ?? null;
const name = decodeHtml(ddp?.name ?? '');
const brand = ddp?.brand ?? null;
const price = num(ddp?.unitPrice);
const salePrice = num(ddp?.unitSalePrice);
const currency = ddp?.currency ?? 'RUB';
const stock = (typeof ddp?.stock === 'number') ? ddp.stock : null;
const url  = ddp?.url ?? (items?.[0]?.json?.url ?? null);

// ---------- CATEGORY: 3 источника ----------
let category = null;

// 1) digitalData.product.category — строка с путём, возьмём последний сегмент
if (typeof ddp?.category === 'string' && ddp.category.trim()) {
  const parts = ddp.category.split('/').filter(Boolean);
  if (parts.length) category = parts[parts.length - 1];
}

// 2) BreadcrumbList из ld+json — берём последний пункт
if (!category) {
  const ldBlocks = [];
  const reLD = /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = reLD.exec(html)) !== null) {
    try {
      const obj = JSON.parse(m[1].trim());
      if (Array.isArray(obj)) ldBlocks.push(...obj);
      else ldBlocks.push(obj);
    } catch {}
  }
  const breadcrumb = ldBlocks.find(x => x && x['@type'] === 'BreadcrumbList');
  if (breadcrumb?.itemListElement?.length) {
    const last = breadcrumb.itemListElement[breadcrumb.itemListElement.length - 1];
    const nameCrumb = (last?.item?.name || last?.name || '').trim();
    if (nameCrumb) category = nameCrumb;
  }
}

// 3) если ничего — оставим null

// ---------- главная картинка ----------
let image = null;
const og = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i);
if (og) image = og[1];

// ---------- SPECS: «бульдозер» по grouped ----------
function extractGroupedArrayChunk(source) {
  let pos = source.search(/specifications\s*["']?\s*:\s*\{/i);
  if (pos === -1) pos = source.search(/["']grouped["']\s*:\s*\[/i);
  if (pos === -1) return null;
  const startGrouped = source.indexOf('[', pos);
  if (startGrouped === -1) return null;
  let i = startGrouped, depth = 0, inStr = false, q = '';
  for (; i < source.length; i++) {
    const ch = source[i], prev = source[i-1];
    if (inStr) { if (ch === q && prev !== '\\') inStr = false; }
    else {
      if (ch === '"' || ch === "'") { inStr = true; q = ch; }
      else if (ch === '[') depth++;
      else if (ch === ']') { depth--; if (depth === 0) { i++; break; } }
    }
  }
  return source.slice(startGrouped, i);
}

let specs_text = '';
(function buildSpecs() {
  let grouped = null;
  const chunk = extractGroupedArrayChunk(html);
  if (chunk) {
    try { grouped = JSON.parse(chunk); }
    catch {
      const sanitized = chunk.replace(/,\s*]/g, ']').replace(/,\s*}/g, '}');
      try { grouped = JSON.parse(sanitized); } catch {}
    }
  }
  if (Array.isArray(grouped) && grouped.length) {
    const parts = [];
    for (const grp of grouped) {
      const title = decodeHtml((grp?.name || 'Характеристики').trim());
      if (title) parts.push(title);
      const items = Array.isArray(grp?.items) ? grp.items : [];
      for (const r of items) {
        const rn = decodeHtml((r?.name || '').trim());
        let rv = '';
        if (Array.isArray(r?.values) && r.values.length) {
          rv = r.values.map(x => decodeHtml(String(x))).join(', ');
        } else if (Array.isArray(r?.items) && r.items.length) {
          rv = r.items.map(x => decodeHtml(x?.title || '')).filter(Boolean).join(', ');
        } else if (typeof r?.value === 'string') {
          rv = decodeHtml(r.value);
        }
        if (rn && rv) parts.push(`- ${rn}: ${rv}`);
      }
      parts.push('');
    }
    specs_text = parts.join('\n').trim();
    return;
  }
  // Fallback: если grouped не нашли — вытащим «Характеристики» куском HTML и очистим
  function stripHtmlToText(s) {
    return decodeHtml(String(s ?? '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n')
      .replace(/<\/(li|div|tr)>/gi, '\n')
      .replace(/<th[^>]*>/gi, '')
      .replace(/<td[^>]*>/gi, ' ')
      .replace(/<[^>]*>/g, '')
      .replace(/\u00A0/g, ' '))
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .replace(/[ \t]{2,}/g, ' ')
      .trim();
  }
  const m =
    html.match(/<h2[^>]*>\s*Характеристики\s*<\/h2>([\s\S]*?)(?:<h2\b|<section\b|<div\b class=["'][^"']*(?:tabs|reviews|accessories)[^"']*["']|$)/i) ||
    html.match(/<section[^>]*?(?:spec|char|характерист)[^>]*>([\s\S]*?)<\/section>/i) ||
    html.match(/<div[^>]*?(?:spec|char|характерист)[^>]*>([\s\S]*?)<\/div>/i);
  if (m) specs_text = stripHtmlToText(m[1]);
})();

const MAX_LEN = 25000;
if (specs_text.length > MAX_LEN) specs_text = specs_text.slice(0, MAX_LEN);

// ---------- результат ----------
return [{
  json: {
    id, sku, mpn, name, brand, category,
    price, salePrice, currency, stock, url, image,
    specs_text
  }
}];
